import{c as s,Q as a,j as t,m as n}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Claude Opus 5 Prompting Masterclass","description":"","frontmatter":{"url":"https://x.com/sairahul1/status/2081681747520209385","title":"Claude Opus 5 Prompting Masterclass","author":"sairahul1","archived":"2026-07-30T00:00:00.000Z","handle":"@sairahul1","published":"2026-07-27T00:00:00.000Z","stats":"325 likes · 38 retweets · 1306 bookmarks · 867327 views","tags":["opus-5","prompt-engineering","effort","scope-control","agentic-narration"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-27-@sairahul1-209385.md","filePath":"research/tweets/2026-07-27-@sairahul1-209385.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-07-27-@sairahul1-209385.md"};function p(i,e,r,l,h,c){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="claude-opus-5-prompting-masterclass-—-sairahul1" tabindex="-1">Claude Opus 5 Prompting Masterclass — @sairahul1 <a class="header-anchor" href="#claude-opus-5-prompting-masterclass-—-sairahul1" aria-label="Permalink to &quot;Claude Opus 5 Prompting Masterclass — @sairahul1&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/sairahul1/status/2081681747520209385" target="_blank" rel="noreferrer">https://x.com/sairahul1/status/2081681747520209385</a><strong>作者</strong>：sairahul1（@sairahul1） <strong>發布日期</strong>：2026-07-27 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Twitter Article <strong>統計</strong>：325 likes · 38 retweets · 1306 bookmarks · 867327 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Anthropic released Claude Opus 5 three days ago.</p><p>They also published an official prompting guide the same day (<a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/prompting-claude-opus-5" target="_blank" rel="noreferrer">https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/prompting-claude-opus-5</a>)</p><p>Almost nobody read it.</p><p>It&#39;s buried in the API docs. Written for developers. Dense enough to make most people bounce in 30 seconds.</p><p>I read it so you don&#39;t have to.</p><p>Here is the full Opus 5 prompting playbook in plain English.</p><p>Every trick. Every prompt template. Every mistake to avoid.</p><p>Save this. It will change how you use Claude.</p><hr><h2 id="first-—-what-is-claude-opus-5" tabindex="-1">First — what is Claude Opus 5? <a class="header-anchor" href="#first-—-what-is-claude-opus-5" aria-label="Permalink to &quot;First — what is Claude Opus 5?&quot;">​</a></h2><p>[圖 1]</p><p>Anthropic just shipped four models in under two months.</p><p>Fable 5 (Mythos) → Sonnet 5 → Opus 5.</p><p>Opus 5 launched July 24, 2026.</p><p>The headline: near-Fable-5 intelligence at half the price.</p><p>→ $5 per million input tokens (vs $10 for Fable 5) → 1 million token context window → Thinking on by default → Built for long, complex, agentic work → Currently leading the Artificial Analysis leaderboard, above even Fable 5</p><p>But here&#39;s what matters more than the specs.</p><p>Opus 5 is a fundamentally different model to prompt.</p><p>The rules that worked for Opus 4.8 now actively hurt you on Opus 5.</p><p>Anthropic removed over 80% of Claude Code&#39;s own system prompt when they upgraded to Opus 5.</p><p>With zero loss on coding benchmarks.</p><p>The guardrails became the problem.</p><p>Here&#39;s what to do instead.</p><p>[圖 2]</p><hr><h2 id="the-effort-dial" tabindex="-1">The Effort Dial <a class="header-anchor" href="#the-effort-dial" aria-label="Permalink to &quot;The Effort Dial&quot;">​</a></h2><p>(The most important control you have)</p><p>[圖 3]</p><p>Opus 5 has one dial that changes everything:</p><p>Effort.</p><p>Four settings:</p><p>→ low — fast, cheap, still surprisingly good → medium — balanced → high — the default. Use this for most things. → xhigh — full power. Reserve for your hardest problems.</p><p>This is not like temperature or other model parameters.</p><p>Effort controls how much the model thinks before responding.</p><p>Higher effort = more reasoning time = better output on hard problems.</p><p>The practical guide:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>low/medium:</span></span>
<span class="line"><span>→ Simple questions</span></span>
<span class="line"><span>→ Quick rewrites</span></span>
<span class="line"><span>→ Basic research</span></span>
<span class="line"><span>→ Conversational replies</span></span>
<span class="line"><span>→ Fast code review passes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>high (default):</span></span>
<span class="line"><span>→ Most tasks</span></span>
<span class="line"><span>→ Code generation</span></span>
<span class="line"><span>→ Analysis</span></span>
<span class="line"><span>→ Writing</span></span>
<span class="line"><span></span></span>
<span class="line"><span>xhigh:</span></span>
<span class="line"><span>→ Complex multi-file coding</span></span>
<span class="line"><span>→ Hard reasoning problems</span></span>
<span class="line"><span>→ Demanding agentic tasks</span></span>
<span class="line"><span>→ Anything where quality is non-negotiable</span></span></code></pre></div><p>The mistake everyone makes:</p><p>They carry their Opus 4.8 effort settings over to Opus 5 without testing.</p><p>Opus 5 is so much better at low/medium that you&#39;re probably overpaying for high effort on tasks that don&#39;t need it.</p><p>Re-run your use cases at lower settings first.</p><p>You&#39;ll be surprised how often low/medium is enough.</p><hr><h2 id="tell-it-why-not-just-what" tabindex="-1">Tell It Why, Not Just What <a class="header-anchor" href="#tell-it-why-not-just-what" aria-label="Permalink to &quot;Tell It Why, Not Just What&quot;">​</a></h2><p>[圖 4]</p><p>This is the biggest shift when moving to Opus 5.</p><p>Old models needed step-by-step instructions.</p><p>Opus 5 needs context and goal.</p><p>It figures out the steps itself — and usually better than you&#39;d specify them.</p><p>The formula Anthropic recommends:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;I&#39;m working on [larger task] for [who it&#39;s for].</span></span>
<span class="line"><span>They need [what the output enables].</span></span>
<span class="line"><span>With that in mind: [your actual request].&quot;</span></span></code></pre></div><p>Example — before:</p><p>&quot;Write a product description for a HVAC calculator app. Include: what it does, key features, benefits, call to action. Keep it under 200 words. Use active voice. Avoid jargon.&quot;</p><p>Example — after:</p><p>&quot;I&#39;m building an iOS calculator app for HVAC contractors. They need to calculate BTU loads, duct sizing, and Manual J heat loss fast on job sites. Write a product description for the App Store.&quot;</p><p>The second prompt is shorter.</p><p>The output is dramatically better.</p><p>Because Opus 5 fills in the right context (contractor audience, on-site use, technical credibility) that you forgot to specify in the first prompt.</p><p>The rule: Give Opus 5 the goal and the why. It will work out the how.</p><hr><h2 id="delete-your-verification-instructions" tabindex="-1">Delete Your Verification Instructions <a class="header-anchor" href="#delete-your-verification-instructions" aria-label="Permalink to &quot;Delete Your Verification Instructions&quot;">​</a></h2><p>This one will feel wrong.</p><p>But Anthropic is explicit about it.</p><p>If your prompts or system instructions contain any of these:</p><p>→ &quot;Include a final verification step&quot; → &quot;Double-check your answer before responding&quot; → &quot;Use a subagent to verify your work&quot; → &quot;Re-verify before completing&quot;</p><p>Delete them all.</p><p>On Opus 4.8, these helped.</p><p>On Opus 5, they hurt.</p><p>Opus 5 already verifies its own work automatically.</p><p>Your instructions to verify stack on top of what it&#39;s already doing.</p><p>The result: wasted tokens, longer responses, no improvement in quality.</p><p>Anthropic tested this directly.</p><p>Removing all verification instructions from their own Claude Code prompts</p><p>→ no loss in quality → significant reduction in cost and tokens.</p><p>The new rule: don&#39;t tell it to check. It already is.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REMOVE THESE from your system prompts:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>❌ &quot;Before responding, verify your answer&quot;</span></span>
<span class="line"><span>❌ &quot;Include a final verification step for non-trivial tasks&quot;</span></span>
<span class="line"><span>❌ &quot;Use a subagent to double-check results&quot;</span></span>
<span class="line"><span>❌ &quot;Re-read your output for errors before sending&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>REPLACE WITH: nothing.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Opus 5 handles this on its own.</span></span></code></pre></div><hr><h2 id="control-verbosity-with-prompts-not-effort" tabindex="-1">Control Verbosity With Prompts, Not Effort <a class="header-anchor" href="#control-verbosity-with-prompts-not-effort" aria-label="Permalink to &quot;Control Verbosity With Prompts, Not Effort&quot;">​</a></h2><p>[圖 5]</p><p>Common mistake: people lower the effort setting to get shorter responses.</p><p>That&#39;s wrong.</p><p>Effort controls how much the model thinks, not how long it talks.</p><p>Lowering effort → less reasoning → worse answers.</p><p>Same response length.</p><p>To control length, use prompts.</p><p>Anthropic&#39;s exact recommended instruction for user-facing products:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Keep responses focused, brief, and concise.</span></span>
<span class="line"><span>Keep disclaimers and caveats short, and spend</span></span>
<span class="line"><span>most of the response on the main answer.</span></span>
<span class="line"><span>When asked to explain something, give a high-level</span></span>
<span class="line"><span>summary unless an in-depth explanation is</span></span>
<span class="line"><span>specifically requested.</span></span></code></pre></div><p>For long system prompts, add a reminder at the end:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tone_preference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Keep outputs reasonably concise.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tone_preference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>For written documents (reports, markdown files) that Opus 5 saves to disk:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Match the length of written documents to what the</span></span>
<span class="line"><span>task needs: cover the substance, but do not pad</span></span>
<span class="line"><span>with filler sections, redundant summaries, or</span></span>
<span class="line"><span>boilerplate.</span></span></code></pre></div><p>Opus 5 defaults to longer, more thorough responses than Opus 4.8.</p><p>That&#39;s usually a feature.</p><p>But for product use cases, you need to dial it back explicitly.</p><hr><h2 id="controlling-agentic-narration" tabindex="-1">Controlling Agentic Narration <a class="header-anchor" href="#controlling-agentic-narration" aria-label="Permalink to &quot;Controlling Agentic Narration&quot;">​</a></h2><p>Opus 5 talks a lot while it works.</p><p>It announces what it&#39;s about to do. It reports what it found. It narrates every step.</p><p>This is fine for personal use.</p><p>For product use cases — where users just want the result — it becomes noise.</p><p>Anthropic&#39;s recommended narration control instruction:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before your first tool call, say in one sentence</span></span>
<span class="line"><span>what you&#39;re about to do.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>While working, give a brief update only when you</span></span>
<span class="line"><span>find something important or change direction.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>When you finish, lead with the outcome: your first</span></span>
<span class="line"><span>sentence should answer &quot;what happened&quot; or &quot;what did</span></span>
<span class="line"><span>you find,&quot; with supporting detail after it for</span></span>
<span class="line"><span>readers who want it.</span></span></code></pre></div><p>The principle: describe the style you want, don&#39;t list what you don&#39;t want.</p><p>Positive examples of communication style work better than &quot;don&#39;t do X&quot; instructions.</p><hr><h2 id="controlling-subagent-spawning" tabindex="-1">Controlling Subagent Spawning <a class="header-anchor" href="#controlling-subagent-spawning" aria-label="Permalink to &quot;Controlling Subagent Spawning&quot;">​</a></h2><p>Opus 5 loves to delegate.</p><p>It spins up subagents automatically for complex tasks.</p><p>That&#39;s powerful when the task genuinely needs parallel work.</p><p>It&#39;s expensive when it doesn&#39;t.</p><p>Without guidance, Opus 5 will delegate tasks you&#39;d have handled in a handful of tool calls.</p><p>The fix — Anthropic&#39;s exact recommended prompt:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Delegate to a subagent only for large tasks that</span></span>
<span class="line"><span>are genuinely independent and parallelizable,</span></span>
<span class="line"><span>such as a wide multi-file investigation.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do not delegate work you can finish yourself</span></span>
<span class="line"><span>in a handful of tool calls, and do not use</span></span>
<span class="line"><span>subagents to verify or double-check your own work.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If one subagent can complete the task, use one</span></span>
<span class="line"><span>rather than several, and keep spawn counts low.</span></span></code></pre></div><p>Rule of thumb: if it&#39;s one coherent task, Opus 5 should handle it.</p><p>Only spawn subagents when the task has truly independent parallel tracks.</p><hr><h2 id="stop-it-from-going-beyond-the-task" tabindex="-1">Stop It from Going Beyond the Task <a class="header-anchor" href="#stop-it-from-going-beyond-the-task" aria-label="Permalink to &quot;Stop It from Going Beyond the Task&quot;">​</a></h2><p>Opus 5 is proactive by design.</p><p>It will add steps you didn&#39;t ask for. It will expand scope because it thinks it&#39;s helping. It will apply its own judgment about what the task should be.</p><p>Sometimes great. Often not what you wanted.</p><p>The scope control prompt:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deliver what was asked, at the scope intended.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Make routine judgment calls yourself, and check in</span></span>
<span class="line"><span>only when different readings of the request would</span></span>
<span class="line"><span>lead to materially different work.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If the request seems mistaken or a better approach</span></span>
<span class="line"><span>exists, say so in a sentence and continue with the</span></span>
<span class="line"><span>task as asked — rather than quietly narrowing,</span></span>
<span class="line"><span>widening, or transforming it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Finish the whole task, and stop short of actions</span></span>
<span class="line"><span>that are clearly beyond what was asked.</span></span></code></pre></div><p>This is the single most important prompt for agentic use cases.</p><p>Opus 5 is powerful enough to go off-script in meaningful ways.</p><p>You need to define the fence.</p><p>[圖 6]</p><hr><h2 id="the-check-in-prompt-for-autonomous-runs" tabindex="-1">The &quot;Check In&quot; Prompt for Autonomous Runs <a class="header-anchor" href="#the-check-in-prompt-for-autonomous-runs" aria-label="Permalink to &quot;The &quot;Check In&quot; Prompt for Autonomous Runs&quot;">​</a></h2><p>Running Opus 5 autonomously on long tasks?</p><p>You need to define when it stops and asks.</p><p>Otherwise it defines its own checkpoints.</p><p>Sometimes fine. For important work — not acceptable.</p><p>Anthropic&#39;s recommended checkpoint prompt:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pause for me only when the work genuinely requires</span></span>
<span class="line"><span>my input:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ A destructive or irreversible action</span></span>
<span class="line"><span>→ A real scope change</span></span>
<span class="line"><span>→ Something only I can provide</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Otherwise, keep going and report back when done.</span></span></code></pre></div><p>This gives Opus 5 permission to run without interrupting you constantly.</p><p>While ensuring it pauses for the moments that actually need you.</p><p>The best of both worlds.</p><hr><h2 id="the-full-optimal-prompt-structure" tabindex="-1">The Full Optimal Prompt Structure <a class="header-anchor" href="#the-full-optimal-prompt-structure" aria-label="Permalink to &quot;The Full Optimal Prompt Structure&quot;">​</a></h2><p>[圖 7]</p><p>Put everything together.</p><p>Every high-quality Opus 5 prompt has four parts:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m working on [larger task] for [who it&#39;s for].</span></span>
<span class="line"><span>They need [what the output enables].</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Request: [your specific ask in one clear sentence]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output format: [exactly how you want the result</span></span>
<span class="line"><span>structured and delivered]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Constraints: [what must not happen on the way</span></span>
<span class="line"><span>to the result]</span></span></code></pre></div><p>Real example — bad prompt:</p><p>&quot;Review this code and find all the bugs. Be thorough. Double-check everything. Report high severity issues first. Verify your findings before responding.&quot;</p><p>Real example — Opus 5 optimized prompt:</p><p>&quot;I&#39;m shipping a HVAC calculator app for iOS this week. The team needs to find real bugs before the App Store submission. Request: Full code review of the attached file. Output format: Numbered list, each bug with: location, what&#39;s wrong, why it matters. Constraints: Report everything you find. Don&#39;t filter by severity — I&#39;ll prioritize separately.&quot;</p><p>Notice: no verification instruction. No &quot;be thorough.&quot; No &quot;double-check.&quot;</p><p>Opus 5 does all of that automatically.</p><p>You just need to get out of the way.</p><hr><h2 id="_6-things-to-watch-out-for" tabindex="-1">6 Things to Watch Out For <a class="header-anchor" href="#_6-things-to-watch-out-for" aria-label="Permalink to &quot;6 Things to Watch Out For&quot;">​</a></h2><p>[圖 8]</p><ol><li>It runs longer than you expect.</li></ol><p>High-effort tasks can take many minutes.</p><p>This is not a bug. It&#39;s thinking.</p><p>Plan for it on complex agentic work.</p><ol start="2"><li>It will go beyond what you asked.</li></ol><p>Opus 5 is proactive by design.</p><p>Use the scope control prompt above for anything sensitive.</p><ol start="3"><li>Your old prompts may hurt you.</li></ol><p>If you have saved prompts or CLAUDE.md files built for Opus 4.8 or earlier — they may produce worse results on Opus 5 than a fresh simple prompt would.</p><p>Start fresh. Then add back only what&#39;s needed.</p><ol start="4"><li>It hallucinates facts slightly more than Opus 4.8.</li></ol><p>Anthropic&#39;s own system card confirms this.</p><p>Opus 5 is confidently wrong more often than its predecessor.</p><p>Verify anything factual before using it.</p><ol start="5"><li>Disabling thinking makes it weird.</li></ol><p>Opus 5 runs with thinking on by default.</p><p>If you turn thinking off, the model occasionally writes tool calls as text instead of actual tool calls. And sometimes emits internal XML tags in its output.</p><p>Anthropic&#39;s recommendation: don&#39;t disable thinking.</p><p>If you need to control cost — use lower effort settings. Don&#39;t kill thinking.</p><ol start="6"><li>Don&#39;t correct narration you don&#39;t care about.</li></ol><p>Opus 5 narrates its own corrections more than Opus 4.8.</p><p>It will say &quot;I said X earlier, I should clarify...&quot;</p><p>Often for corrections the user doesn&#39;t care about.</p><p>The fix:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Only correct an earlier statement when the error</span></span>
<span class="line"><span>would change the user&#39;s code, conclusions, or</span></span>
<span class="line"><span>decisions.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>State corrections plainly and briefly, then</span></span>
<span class="line"><span>continue the task.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For slips that change nothing for the user,</span></span>
<span class="line"><span>make the fix and move on without noting it.</span></span></code></pre></div><hr><h2 id="quick-reference-—-all-key-prompts" tabindex="-1">Quick Reference — All Key Prompts <a class="header-anchor" href="#quick-reference-—-all-key-prompts" aria-label="Permalink to &quot;Quick Reference — All Key Prompts&quot;">​</a></h2><p>Copy these into your system prompts now.</p><p>Conciseness (user-facing products):</p><blockquote><p>Keep responses focused, brief, and concise. Spend most of the response on the main answer.</p></blockquote><p>Narration control (agentic tasks):</p><blockquote><p>Before your first tool call, say in one sentence what you&#39;re about to do. Brief updates only when something important turns up. Lead with the outcome when done.</p></blockquote><p>Scope control (narrow tasks):</p><blockquote><p>Deliver what was asked, at the scope intended. Say so if a better approach exists, then do the task as asked.</p></blockquote><p>Checkpoint control (autonomous runs):</p><blockquote><p>Pause only for: destructive actions, real scope changes, or things only I can provide. Otherwise keep going.</p></blockquote><p>Subagent control (cost management):</p><blockquote><p>Delegate only for large genuinely parallel tasks. Don&#39;t delegate what you can handle in a few tool calls. Keep spawn counts low.</p></blockquote><p>Correction narration:</p><blockquote><p>Only correct earlier statements when the error changes the user&#39;s conclusions. Make small fixes and move on without noting them.</p></blockquote><hr><h2 id="the-core-lesson-from-anthropic" tabindex="-1">The core lesson from Anthropic <a class="header-anchor" href="#the-core-lesson-from-anthropic" aria-label="Permalink to &quot;The core lesson from Anthropic&quot;">​</a></h2><p>Most people respond to a misbehaving model by adding more instructions.</p><p>Anthropic&#39;s engineers did the opposite.</p><p>They removed instructions until the model could breathe.</p><p>The constraint was the problem.</p><p>Opus 5 is smart enough to figure out the right approach itself — if you stop telling it the wrong approach.</p><p>Give it the goal. Give it the why. Get out of the way.</p><p>That is the entire Opus 5 prompting philosophy.</p><hr><p>If this was useful:</p><p>→ Repost to share it with every Claude power user you know → Follow @sairahul1 for more playbooks like this → Bookmark this — the prompt templates work, use them today</p><p>Subscribe to theaibuilders.co for more such interesting articles</p><p>I write about AI, building products, and systems that work while you sleep.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Opus 5 官方 prompting 指南精華——effort dial 取代冗長指令、砍掉自我驗證指令、用 prompt（非 effort）控制輸出長度、明確劃 scope/checkpoint 邊界。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>Effort dial</strong>（low/medium/high/xhigh）是 Opus 5 最重要的控制項；舊模型的 effort 慣例沿用到 Opus 5 上大機率過度花費，應重新從低檔測起</li><li><strong>給目標不給步驟</strong>：舊模型需要逐步指令，Opus 5 只需 context + goal 就能自行推導步驟，且通常優於人工指定的步驟</li><li><strong>刪除自我驗證指令</strong>：Opus 5 已內建自我驗證，額外要求「double-check」「re-verify」只會疊加 token 成本，Anthropic 官方測試移除後品質不降、成本顯著下降</li><li><strong>verbosity 用 prompt 控制，不用 effort</strong>：effort 控制思考量非輸出長度，降 effort 只會讓答案變差、長度不變</li><li><strong>scope control / checkpoint control / subagent control</strong> 三類 prompt 樣板，用於防止 Opus 5 過度自主擴權、過度委派、或未經確認執行破壞性動作</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Opus 5：$5/M input tokens（Fable 5 為 $10/M）、1M context window、預設開啟 thinking</li><li>Claude Code 系統提示詞在升級 Opus 5 時砍除超過 80%，coding benchmark 零損失</li><li>官方原始來源：<code>platform.claude.com/docs/.../prompting-claude-opus-5</code></li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>本文所有樣板 prompt 與本 workspace <code>output-discipline.md</code>（簡潔直接）、<code>core.md §APPLY</code>（scope 有變更才問）、<code>graph.md §G4</code>（Handoff Contract 邊界明確）的既有規則<strong>高度重疊甚至幾乎逐句對應</strong>，可視為對現有規則設計方向的外部官方驗證，而非新增知識</li><li>未附測試方法論或量化基準（除「80% 系統提示詞刪減、benchmark 零損失」一句未附連結佐證），可信度依賴對 Anthropic 官方文件的轉述準確性，未獨立查核原文</li><li>「刪除驗證指令」建議與本 workspace <code>core.md §TEST</code> 的 <code>unverified_success</code> 閘門存在潛在張力——需注意此建議適用於「模型自身推理品質」場景，不適用於本 workspace 要求的<strong>外部確定性驗證閘門</strong>（gate 仍須親跑，屬不同層次的驗證）</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>樣板 prompt 可直接比對 / 補強既有 rules，但多數內容已被既有規則涵蓋，邊際新增有限</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>轉述官方文件而非原創觀點，價值在於整理與案例化</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>引用官方文件連結，但核心數字（80% 刪減）未附獨立驗證來源，社群推文上限 6</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>六組可直接複製的樣板 prompt，附 before/after 對照範例</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用任何使用 Opus 5 的 prompt/CLAUDE.md 設計場景，跨任務通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.1/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule（外部驗證，非新增） <strong>理由</strong>：核心樣板與本 workspace 既有 <code>core.md</code>/<code>output-discipline.md</code>/<code>graph.md</code> 高度重疊，建議標注為「官方指南對照佐證」而非直接改動規則檔；若要整合，優先確認 <code>core.md §TEST</code> 與「刪除驗證指令」建議的適用邊界不衝突。</p>`,224)])])}const g=s(o,[["render",p]]);export{d as __pageData,g as default};
